/// <summary>
/// PricingAttribute of table <c>CustTable</c> field InventLocation.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventLocation, InventLocationId))]
internal class GUPPricingAttributeInventLocationInventLocationId extends GUPPricingAttributeInventLocation implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventLocation, InventLocationId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    InventLocation inventLocation;

    while select InventLocation from custtable
        group by InventLocation
        join inventLocation
        group by InventLocationid, Name
        where custTable.InventLocation == inventLocation.InventLocationid
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(inventLocation.InventLocationid, inventLocation.Name);
        ret.add(valueObject);
    }
    return ret;
}
